from __future__ import annotations

import streamlit as st


def inject_styles() -> None:
    st.markdown(r"""
<style>
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');
:root{--bg:#030a1f;--bg2:#061a45;--panel:rgba(7,24,60,.78);--panel2:rgba(12,34,84,.62);--line:rgba(77,140,255,.28);--blue:#1f8bff;--cyan:#22e0c0;--violet:#a96cff;--text:#f2f6ff;--muted:#9db4dd}
.stApp{font-family:'Plus Jakarta Sans',system-ui,sans-serif;color:var(--text);background:radial-gradient(800px 500px at 88% 12%,rgba(31,139,255,.28),transparent 62%),radial-gradient(700px 500px at 8% 0%,rgba(20,104,214,.22),transparent 62%),linear-gradient(160deg,var(--bg),var(--bg2) 58%,#08235a)}
#MainMenu,footer,header{visibility:hidden}.block-container{max-width:1520px;padding:0 18px 24px}
.topbar{height:64px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(77,140,255,.16);margin:0 -18px 14px;padding:0 24px;background:rgba(3,10,31,.72);backdrop-filter:blur(16px)}
.brand{display:flex;align-items:center;gap:12px}.brand-mark{font-size:32px;color:#3aa0ff;text-shadow:0 0 18px rgba(58,160,255,.9)}.brand-name{font-size:26px;font-weight:800}.brand-name span{color:#3aa0ff}.brand-divider{height:30px;width:1px;background:var(--line)}.brand-sub{font-size:15px;color:var(--muted)}
.nav-wrap{display:flex;align-items:center;justify-content:flex-end;gap:8px}.nav-wrap .stButton>button{height:42px;border-radius:10px!important;background:transparent!important;border:1px solid transparent!important;color:#d6e3ff!important;font-weight:600!important}.nav-wrap .stButton>button:hover{background:rgba(31,139,255,.14)!important}.nav-wrap .active>button{background:linear-gradient(180deg,#1f8bff,#1468d6)!important;color:#fff!important}.nav-wrap .outline>button{border-color:var(--line)!important}.nav-wrap .primary>button{background:linear-gradient(180deg,#2b97ff,#1468d6)!important;color:white!important}
.hero{display:grid;grid-template-columns:1.08fr .92fr;gap:48px;align-items:center;min-height:540px}.eyebrow{display:inline-flex;padding:8px 17px;border:1px solid #2c78db;border-radius:999px;color:#72bbff;background:rgba(31,139,255,.08);font-weight:600}.hero h1{font-size:clamp(44px,6vw,76px);line-height:1.03;letter-spacing:-3px;margin:24px 0 18px}.gradient{background:linear-gradient(90deg,#3aa0ff,#b07cff);-webkit-background-clip:text;color:transparent}.hero-copy{color:var(--muted);font-size:18px;line-height:1.7;max-width:620px;margin-bottom:26px}.feature-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin:20px 0 34px}.feature,.glass{background:var(--panel2);border:1px solid var(--line);border-radius:18px}.feature{padding:20px}.feature-icon{width:48px;height:48px;border-radius:14px;display:grid;place-items:center;background:linear-gradient(145deg,#12388a,#0b2253);color:#4aa8ff;font-size:24px;margin-bottom:12px}.feature h3{font-size:16px;margin:0 0 6px}.feature p,.muted{color:var(--muted);font-size:13px;margin:0}.aura-stage{position:relative;width:min(420px,90%);aspect-ratio:1;margin:auto}.aura-stage:before{content:"";position:absolute;inset:-16px;border-radius:50%;border:2px solid rgba(31,139,255,.7);box-shadow:0 0 55px rgba(31,139,255,.35),inset 0 0 40px rgba(31,139,255,.15)}.aura-stage img{width:100%;height:100%;object-fit:cover;object-position:50% 15%;border-radius:50%;border:3px solid rgba(80,160,255,.8)}.aura-bubble{position:absolute;right:-28px;bottom:-30px;background:#0b2253;border:1px solid var(--line);border-radius:18px;padding:14px 18px;box-shadow:0 18px 40px rgba(0,0,0,.45)}.aura-bubble b{display:block}.aura-bubble span{font-size:13px;color:var(--muted)}
.section{padding:70px 0;border-top:1px solid rgba(77,140,255,.18)}.section h2{font-size:36px;margin:0 0 10px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.glass{padding:22px}.glass h3{color:#7db8ff;font-size:16px}.glass p{color:var(--muted);font-size:14px}
.footer{border-top:1px solid rgba(77,140,255,.18);padding:24px 0;color:var(--muted);font-size:13px;display:flex;justify-content:space-between}
/* Streamlit button styling */
.stButton>button,.stFormSubmitButton>button{border-radius:12px!important;border:1px solid var(--line)!important;background:rgba(31,139,255,.10)!important;color:#eaf3ff!important;font-weight:600!important;transition:.18s}.stButton>button:hover,.stFormSubmitButton>button:hover{border-color:rgba(77,160,255,.7)!important;background:rgba(31,139,255,.2)!important}.primary-btn>button,.stFormSubmitButton>button[kind="primary"]{background:linear-gradient(180deg,#2b97ff,#1468d6)!important;border-color:transparent!important;box-shadow:0 8px 24px rgba(31,139,255,.35)!important}
/* Dashboard */
.dash{display:grid;grid-template-columns:278px minmax(520px,1fr) 350px;gap:18px;height:calc(100vh - 100px);min-height:720px}.panel{background:rgba(7,24,60,.68);border:1px solid var(--line);border-radius:18px;overflow:hidden}.side{display:flex;flex-direction:column;min-height:0}.side-menu{padding:12px}.side-menu .stButton>button{display:flex;justify-content:flex-start;text-align:left;background:transparent!important;border-color:transparent!important;height:46px}.side-menu .selected>button{background:linear-gradient(180deg,#1f8bff,#1468d6)!important;color:#fff!important;box-shadow:0 6px 18px rgba(31,139,255,.35)!important}.progress-card{padding:18px;margin-top:16px}.progress-row{display:flex;align-items:center;gap:14px}.ring{--p:0;width:70px;height:70px;border-radius:50%;background:conic-gradient(#1f8bff calc(var(--p)*1%),rgba(255,255,255,.09) 0);display:grid;place-items:center;flex:none}.ring>div{width:54px;height:54px;border-radius:50%;background:#0a2054;display:grid;place-items:center;font-weight:700}.recent{margin-top:16px;padding:16px;overflow:auto;flex:1}.chat-row{padding:12px 4px;border-bottom:1px solid rgba(77,140,255,.14)}.chat-row b{font-size:12px}.chat-row small{color:var(--muted);display:block;font-size:11px;margin-top:4px}
.chat-panel{display:flex;flex-direction:column;min-width:0}.chat-head{height:66px;display:flex;align-items:center;justify-content:space-between;padding:0 20px;border-bottom:1px solid var(--line)}.chat-title{display:flex;align-items:center;gap:12px}.spark{color:#3aa0ff;font-size:28px}.online{padding:7px 14px;border:1px solid rgba(34,224,192,.5);border-radius:999px;color:#7df0d8;font-size:12px}.msg-area{padding:18px 20px;overflow:auto;flex:1}.bubble{max-width:88%;padding:14px 18px;border-radius:18px;background:rgba(20,52,120,.7);border:1px solid var(--line);margin:0 0 16px;font-size:14px;line-height:1.65}.bubble.me{margin-left:auto;background:linear-gradient(180deg,#1b4a9a,#143b80);border-top-right-radius:6px}.bubble.assistant{border-top-left-radius:6px}.bubble small{display:block;text-align:right;color:var(--muted);font-size:10px;margin-top:5px}.section-box{background:rgba(7,22,60,.65);border:1px solid var(--line);border-radius:14px;padding:14px;margin:12px 0}.section-box h5{color:#4db3ff;font-size:13px;margin:0 0 4px}.section-box ul{margin:5px 0 0;padding-left:18px;color:#dbe7ff;font-size:12px}.chip-row{display:flex;gap:8px;flex-wrap:wrap;padding:0 18px 10px}.input-row{padding:0 18px 18px}.input-row input{background:rgba(3,10,31,.55)!important;color:#fff!important}
.right-panel{overflow:auto}.aura-card{padding:18px}.aura-pic{width:230px;height:250px;margin:auto;position:relative}.aura-pic:before{content:"";position:absolute;inset:0 8px 22px;border-radius:50%;border:2px solid rgba(31,139,255,.7);box-shadow:0 0 40px rgba(31,139,255,.4)}.aura-pic img{position:absolute;left:50%;top:0;transform:translateX(-50%);width:210px;height:250px;object-fit:cover;object-position:50% 15%;border-radius:50% 50% 14px 14px;mask-image:linear-gradient(#000 70%,transparent)}.aura-card h2{margin:-28px 0 0;font-size:29px}.aura-card h2 span{font-size:11px;background:#1f8bff;padding:3px 8px;border-radius:7px}.fact{display:flex;gap:12px;align-items:center;padding:12px 16px;border-bottom:1px solid rgba(77,140,255,.14)}.fact:last-child{border:0}.fact-icon{width:40px;height:40px;border-radius:12px;display:grid;place-items:center;background:rgba(31,139,255,.18);color:#7db8ff;flex:none}.fact b{font-size:12px;display:block}.fact small{color:var(--muted);font-size:10px}.quick{padding:16px}.quick h4{margin:0 0 10px}.quote{padding:12px 16px;color:#b9cdf0;font-size:11px}.profile-pill{display:flex;align-items:center;gap:8px}.profile-pill img{width:32px;height:32px;border-radius:50%;border:1px solid var(--line)}
[data-testid="stDialog"]{background:linear-gradient(170deg,#0d2a66,#071a45)!important;border:1px solid var(--line)!important;border-radius:20px!important}.auth-note{color:var(--muted);font-size:13px}.error{color:#ff8d99}.success{color:#7df0d8}
@media(max-width:1250px){.dash{grid-template-columns:250px minmax(0,1fr)}.right-panel{display:none}}@media(max-width:900px){.hero{grid-template-columns:1fr}.feature-grid,.cards{grid-template-columns:1fr 1fr}.dash{grid-template-columns:1fr}.side{display:none}}@media(max-width:600px){.feature-grid,.cards{grid-template-columns:1fr}.brand-sub,.brand-divider{display:none}.hero h1{font-size:44px}.aura-bubble{right:0}}
</style>
""", unsafe_allow_html=True)
